//!
//! P2 rests on no axiom. What it does not say: that the next hop reads the
//! frame the same way.
//! A1 rests on no axiom. It says nothing about who hands leases out, or when
//! one may be reused.
//!
//! # Layers
//!
//! A module uses modules of its own layer and of the layers below, and no
//! other. Each module's header names its layer.
//!
//! | Layer | Modules | Rule |
//! |---|---|---|
//! | 0, leaves | [`plan`], [`time`] | a value with one meaning; no module of the crate is used |
//! | 1, bounded tables | [`flow`], [`ledger`], [`notes`], [`pins`], [`pool`], [`slab`], [`sweep`] | capacity fixed when the table is made; every operation says what it removes |
//! | 2, readers | [`dnsa`], [`dnsq`], [`frame`] | total and bounded; one reading; equal to a written specification; nothing else is read |
//! | 3, policy to rules | [`alias`], [`policy`], [`rebind`], [`row`] | one constructor; what is not enforced is named |
//! | 4, decisions | [`answer`], [`cohort`], [`judge`], [`node`], [`origin`], [`route`] | a decision is a table: one arm a case, in order |
//! | 5, composition | [`finish`], [`gate`], [`ingress`], [`isolation`], [`report`], [`split`] | decides nothing the layers below did not; every admit has a reason |
#![expect(
    clippy::indexing_slicing,
    reason = "Verus proves every index in the verified functions in bounds: no panic path"
)]
#![expect(
    clippy::manual_map,
    clippy::len_without_is_empty,
    clippy::collapsible_if,
    reason = "the kernel keeps the explicit matches, comparisons and arithmetic its proofs are written against"
)]
#![expect(
    clippy::too_many_arguments,
    reason = "the gate's constructor and its DNS entry points take each part and each list by name; a struct of arguments would be one more type to specify"
)]
#![expect(
    clippy::ptr_arg,
    reason = "`reset_rows` is specified over the vector the gate owns; a slice would need a second view in its contract"
)]
#![forbid(unsafe_code)]
#![cfg_attr(verus_keep_ghost, feature(proc_macro_hygiene))]
#![cfg_attr(
    not(test),
    deny(clippy::unwrap_used, clippy::expect_used, clippy::panic)
)]

